// A triangle cut off by the coordinate axes and an intercept line.
//
// size(W,H) bounds the output under Asymptote's default keepAspect and does not
// scale labels, so the compiler decides the box. This declaration is restated from
// a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,240);
draw((0,0)--(4,0)--(0,6)--cycle);
draw((0,0)--(4.6,0),Arrow);
draw((0,0)--(0,6.6),Arrow);
label("$x$",(4.7,0),E);
label("$y$",(0,6.7),N);
label("$A$",(4,0),SE);
label("$B$",(0,6),NW);
label("$4$",(2,0),S);
label("$6$",(-0.35,3),E);
label("$\frac{x}{4}+\frac{y}{6}=1$",(1.9,2.4),NE);
